import {
  ChangeDetectionStrategy, Component, TemplateRef, ViewEncapsulation, computed, input, model, output,
} from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';
import { HrmAlert, HrmAlertType, HrmApprovalFlow, HrmApprovalStep, HrmEmpty } from 'hrm-ui';

/**
 * @file Form Design System — bộ shell dùng chung cho MỌI form nghiệp vụ HRM.
 *
 * Ý TƯỞNG CỐT LÕI: form KHÔNG phân loại theo tên nghiệp vụ (LeaveForm/TripForm/...),
 * mà theo **Layout × Trait**:
 *   - 5 Layout: flat · sectioned · repeatable · table · checklist
 *   - 11 Trait: effective-dated · comparison · calendar-context · money-policy · attachment ·
 *               approval · audit · sensitive-permission · conflict · bulk-target · import-map
 * Nghiệp vụ mới = chọn 1 layout + N trait ⇒ thêm cấu hình, KHÔNG thêm component.
 *
 * SỐ CỘT bám **bề rộng container** (CSS Container Queries), KHÔNG bám tên chế độ mở
 * (bảng+chi tiết / cạnh danh sách / giữa màn hình / toàn trang / tab mới). Cùng một form
 * dùng chung cho cả 5 chế độ.
 *
 * File này là ỨNG VIÊN để chuyển lên `libs/hrm-ui` sau khi nghiệm thu trên template.
 */

// ══════════════════════════════════════════════════════════════════════════════
// LAYOUT — shell + grid + section + field
// ══════════════════════════════════════════════════════════════════════════════

/** Kích thước NGỮ NGHĨA của field — không phải số cột. Shell tự quy đổi theo container. */
export type VnrFieldSize = 'sm' | 'md' | 'lg' | 'full';

@Component({
  selector: 'vnr-form-shell',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  template: `<div class="vnr-fs" [class.is-compact]="compact()"><ng-content /></div>`,
  styles: [`
    /* Shell CHỈ tạo container context.
       ⚠ KHÔNG khai --vnr-cols ở đây: một phần tử KHÔNG thể query container của CHÍNH NÓ,
       chỉ hậu duệ mới query được. Khai ở đây ⇒ mọi @container im lặng không áp dụng,
       cột kẹt = 1 trong khi span của field vẫn nhảy ⇒ sinh cột ngầm, layout sai âm thầm. */
    .vnr-fs { container-type: inline-size; container-name: vnrform;
      --vnr-gx: var(--space-4, 16px); --vnr-gy: var(--space-4, 16px); inline-size: 100%; }
    .vnr-fs.is-compact { --vnr-gx: var(--space-3, 12px); --vnr-gy: var(--space-2-5, 10px); }

    /* Số cột khai trên GRID (hậu duệ) ⇒ @container mới có hiệu lực */
    .vnr-fg { --vnr-cols: 1; display: grid; grid-template-columns: repeat(var(--vnr-cols), minmax(0, 1fr));
      column-gap: var(--vnr-gx); row-gap: var(--vnr-gy); align-items: start; }
    @container vnrform (min-width: 480px)  { .vnr-fg { --vnr-cols: 2; } }
    @container vnrform (min-width: 760px)  { .vnr-fg { --vnr-cols: 3; } }
    @container vnrform (min-width: 1080px) { .vnr-fg { --vnr-cols: 4; } }

    /* ⚠ Grid item THẬT là phần tử host <vnr-form-field>, KHÔNG phải .vnr-ff bên trong.
       Đặt grid-column lên .vnr-ff sẽ không có tác dụng (đã đo: field size="full" vẫn chỉ 1 cột). */
    .vnr-fg > vnr-form-field { grid-column: span 1; min-inline-size: 0; display: block; }
    .vnr-fg > vnr-form-field[data-size='full'] { grid-column: 1 / -1; }
    @container vnrform (min-width: 480px) { .vnr-fg > vnr-form-field[data-size='lg'] { grid-column: span 2; } }
    .vnr-ff { min-inline-size: 0; }

    .vnr-sec { border-block-end: 1px solid var(--border-soft);
      padding-block: var(--space-4, 16px); }
    .vnr-sec:last-of-type { border-block-end: none; }
    .vnr-sec__hd { display: flex; align-items: center; gap: var(--space-2, 8px); margin-block-end: var(--space-3, 12px); }
    .vnr-sec__t { font-size: var(--fs-14, 14px); font-weight: var(--font-semibold, 600); color: var(--text-strong); }
    .vnr-sec__m { margin-inline-start: auto; font-size: var(--fs-12, 12px); color: var(--text-soft);
      font-variant-numeric: tabular-nums; }

    .vnr-ff__lb { display: block; }
    .vnr-ff__lbt { display: block; font-size: var(--fs-12, 12px); font-weight: var(--font-medium, 500);
      color: var(--text-body); margin-block-end: var(--space-1, 4px); }
    .vnr-ff__lbt .rq { color: var(--error-base); margin-inline-start: 2px; }
    .vnr-ff__hint { font-size: var(--fs-11, 11px); color: var(--text-soft); margin-block-start: var(--space-1, 4px); }
    .vnr-ff__err { font-size: var(--fs-11, 11px); color: var(--error-base); margin-block-start: var(--space-1, 4px); }
    /* Control của hrm-ui luôn chiếm trọn bề ngang ô field */
    .vnr-ff hrm-input, .vnr-ff hrm-select, .vnr-ff hrm-textarea,
    .vnr-ff hrm-date-picker, .vnr-ff hrm-input-number { display: block; inline-size: 100%; }
  `],
})
export class VnrFormShell {
  readonly compact = input(false);
}

@Component({
  selector: 'vnr-form-grid',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `<div class="vnr-fg"><ng-content /></div>`,
})
export class VnrFormGrid {}

@Component({
  selector: 'vnr-form-section',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <section class="vnr-sec">
      <header class="vnr-sec__hd">
        <span class="vnr-sec__t">{{ title() }}</span>
        @if (meta()) { <span class="vnr-sec__m">{{ meta() }}</span> }
        <ng-content select="[secActions]" />
      </header>
      <ng-content />
    </section>
  `,
})
export class VnrFormSection {
  readonly title = input.required<string>();
  /** Vd trạng thái hoàn thiện "6/7". */
  readonly meta = input<string | null>(null);
}

@Component({
  selector: 'vnr-form-field',
  changeDetection: ChangeDetectionStrategy.OnPush,
  // data-size đặt trên HOST vì host mới là grid item của .vnr-fg
  host: { '[attr.data-size]': 'size()' },
  // <label> BỌC control (thay vì để control ngoài label) ⇒ liên kết nhãn–ô nhập theo chuẩn HTML:
  // bấm nhãn là focus vào ô, và trình đọc màn hình đọc đúng tên trường. Không cần sinh id.
  template: `
    <div class="vnr-ff">
      <label class="vnr-ff__lb">
        <span class="vnr-ff__lbt">{{ label() }}@if (required()) {<span class="rq">*</span>}</span>
        <ng-content />
      </label>
      @if (error()) { <div class="vnr-ff__err">{{ error() }}</div> }
      @else if (hint()) { <div class="vnr-ff__hint">{{ hint() }}</div> }
    </div>
  `,
})
export class VnrFormField {
  readonly label = input.required<string>();
  readonly size = input<VnrFieldSize>('md');
  readonly required = input(false);
  readonly hint = input<string | null>(null);
  readonly error = input<string | null>(null);
}

// ══════════════════════════════════════════════════════════════════════════════
// TRAIT · calendar-context
// ══════════════════════════════════════════════════════════════════════════════

export type VnrDayKind = 'workday' | 'weekend' | 'holiday' | 'locked';

export interface VnrCalendarDay {
  /** ISO yyyy-MM-dd — khoá so sánh, tránh lệch múi giờ. */
  readonly date: string;
  readonly day: number;
  readonly kind: VnrDayKind;
  readonly conflict?: string | null;
  readonly shift?: string | null;
  /** 1 = cả ngày · 0.5 = nửa ngày. */
  readonly portion?: number;
}

export interface VnrCalendarSummaryItem {
  readonly label: string;
  readonly value: string;
  readonly tone?: 'normal' | 'warn' | 'success';
}

/**
 * Lịch mang NGỮ CẢNH NGHIỆP VỤ (ngày lễ/nghỉ tuần/khoá/xung đột/ca/nửa ngày).
 * RANH GIỚI: component KHÔNG tự quyết ngày nào lễ/khoá, KHÔNG tự tính số ngày công —
 * domain service tính sẵn rồi truyền vào. Nhờ vậy dùng chung được cho nghỉ phép, công tác,
 * đăng ký ca, đào tạo… mà không nhét luật của nghiệp vụ nào vào UI.
 */
@Component({
  selector: 'vnr-hr-calendar',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  template: `
    <div class="vnr-cal">
      <div class="vnr-cal__bar">
        <span class="vnr-cal__title">{{ monthLabel() }}</span>
        @if (selected().length) {
          <button type="button" class="vnr-cal__clear" (click)="clear()">Bỏ chọn ({{ selected().length }})</button>
        }
      </div>
      <div class="vnr-cal__grid">
        @for (d of dow; track d) { <div class="vnr-cal__dow">{{ d }}</div> }
        @for (d of days(); track d.date) {
          <button type="button" class="vnr-cal__day"
            [class.is-sel]="isSel(d.date)" [class.is-range]="inRange(d.date)"
            [attr.data-kind]="d.kind" [disabled]="d.kind === 'locked'"
            [attr.aria-label]="dayLabel(d)" [attr.aria-pressed]="isSel(d.date) || inRange(d.date)"
            [title]="d.conflict || ''" (click)="pick(d)">
            <span>{{ d.day }}</span>
            @if (d.shift) { <span class="vnr-cal__shift">{{ d.shift }}</span> }
            @if (d.portion === 0.5) { <span class="vnr-cal__half"></span> }
            @if (d.conflict) { <span class="vnr-cal__cf"></span> }
          </button>
        }
      </div>
      <div class="vnr-cal__lg">
        @for (l of legend(); track l.kind) { <span><i [attr.data-kind]="l.kind"></i>{{ l.label }}</span> }
        @if (hasConflict()) { <span><i class="cf"></i>Xung đột lịch</span> }
      </div>
      @if (summary().length) {
        <div class="vnr-cal__sum">
          @for (s of summary(); track s.label) {
            <div [attr.data-tone]="s.tone || 'normal'"><span class="k">{{ s.label }}</span><span class="v">{{ s.value }}</span></div>
          }
        </div>
      }
    </div>
  `,
  styles: [`
    .vnr-cal { border: 1px solid var(--border-sub); border-radius: var(--radius-sm, 6px); background: var(--bg-surface); overflow: hidden; }
    .vnr-cal__bar { display: flex; align-items: center; gap: 8px; padding: 8px 12px; border-block-end: 1px solid var(--border-soft); }
    .vnr-cal__title { font-weight: var(--font-semibold, 600); font-size: var(--fs-13, 13px); }
    .vnr-cal__clear { margin-inline-start: auto; border: none; background: none; color: var(--primary-base); font-size: var(--fs-12, 12px); font-weight: var(--font-medium, 500); cursor: pointer; }
    .vnr-cal__grid { display: grid; grid-template-columns: repeat(7, 1fr); }
    .vnr-cal__dow { text-align: center; font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); color: var(--text-soft); background: var(--bg-surface-subtle); padding-block: 6px; }
    /* ⚠ KHÔNG aspect-ratio:1 — container rộng ⇒ ô phình cao vô ích (đo được ~128px @900px).
       Dùng đơn vị container-query cqi + clamp ⇒ ô co giãn CÓ TRẦN.
       (Lưu ý: KHÔNG đặt dấu backtick trong comment CSS — nó đóng template literal sớm,
        biến styles thành mảng nhiều phần tử ⇒ lỗi "Failed to resolve styles at position 1".) */
    .vnr-cal__day { position: relative; block-size: clamp(32px, 6cqi, 48px); display: flex; align-items: center; justify-content: center;
      border: none; border-block-start: 1px solid var(--border-soft); border-inline-end: 1px solid var(--border-soft);
      background: var(--bg-surface); color: var(--text-strong); font: inherit; font-size: var(--fs-12, 12px); cursor: pointer; }
    .vnr-cal__day:focus-visible { outline: 2px solid var(--text-strong); outline-offset: -3px; z-index: 1; }
    .vnr-cal__day:hover:not(:disabled) { background: var(--primary-bg-subtle); }
    .vnr-cal__day:disabled { cursor: not-allowed; }
    .vnr-cal__day[data-kind='weekend'] { background: var(--bg-surface-subtle); color: var(--text-sub); }
    .vnr-cal__day[data-kind='holiday'] { background: var(--error-bg); color: var(--error-base); font-weight: var(--font-semibold, 600); }
    .vnr-cal__day[data-kind='locked']  { background: var(--faded-bg); color: var(--text-soft); text-decoration: line-through; }
    .vnr-cal__day.is-range { background: var(--primary-bg-subtle); color: var(--primary-base); }
    .vnr-cal__day.is-sel   { background: var(--primary-base); color: var(--text-on-primary); font-weight: var(--font-semibold, 600); }
    /* 9px nằm DƯỚI đáy thang chữ của design system (--fs-10 là nhỏ nhất) ⇒ nâng lên bậc hợp lệ.
       Cỡ chữ ngoài thang cũng không co giãn theo --font-scale nên phá luôn tính năng phóng chữ. */
    .vnr-cal__shift { position: absolute; inset-block-end: 2px; font-size: var(--fs-10, 10px); opacity: .85; }
    /* Nửa ngày: nêm chéo — đọc được cả khi mù màu, không chỉ dựa vào màu */
    .vnr-cal__half { position: absolute; inset: 0; background: linear-gradient(135deg, transparent 50%, currentColor 50%); opacity: .22; pointer-events: none; }
    .vnr-cal__cf { position: absolute; inset-block-start: 3px; inset-inline-end: 3px; inline-size: 6px; block-size: 6px; border-radius: var(--radius-full); background: var(--warning-base); }
    .vnr-cal__lg { display: flex; flex-wrap: wrap; gap: 12px; padding: 8px 12px; border-block-start: 1px solid var(--border-soft); font-size: var(--fs-11, 11px); color: var(--text-sub); }
    .vnr-cal__lg i { inline-size: 10px; block-size: 10px; border-radius: var(--radius-2xs, 2px); display: inline-block; margin-inline-end: var(--space-1, 4px); vertical-align: -1px; border: 1px solid var(--border-sub); background: var(--bg-surface); }
    .vnr-cal__lg i[data-kind='weekend'] { background: var(--bg-surface-subtle); }
    .vnr-cal__lg i[data-kind='holiday'] { background: var(--error-bg); border-color: var(--error-base); }
    .vnr-cal__lg i[data-kind='locked']  { background: var(--faded-bg); }
    .vnr-cal__lg i.cf { background: var(--warning-base); border-color: var(--warning-base); border-radius: var(--radius-full); }
    .vnr-cal__sum { display: flex; flex-wrap: wrap; gap: 10px; padding: 10px 12px; border-block-start: 1px solid var(--border-soft); background: var(--bg-surface-subtle); }
    .vnr-cal__sum > div { display: flex; align-items: baseline; gap: 6px; font-size: var(--fs-12, 12px); }
    .vnr-cal__sum .k { color: var(--text-sub); }
    .vnr-cal__sum .v { font-weight: var(--font-semibold, 600); font-variant-numeric: tabular-nums; }
    .vnr-cal__sum > div[data-tone='warn'] .v { color: var(--warning-base); }
    .vnr-cal__sum > div[data-tone='success'] .v { color: var(--success-base); }
  `],
})
export class VnrHrCalendar {
  readonly days = input.required<readonly VnrCalendarDay[]>();
  readonly monthLabel = input.required<string>();
  readonly selected = model<readonly string[]>([]);
  readonly summary = input<readonly VnrCalendarSummaryItem[]>([]);
  readonly selectionChange = output<readonly string[]>();

  protected readonly dow = ['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'];

  /** Chú giải chỉ liệt kê loại ngày THỰC SỰ có trong tháng — giảm nhiễu. */
  protected readonly legend = computed(() => {
    const label: Record<VnrDayKind, string> = {
      workday: 'Ngày làm việc', weekend: 'Ngày nghỉ tuần', holiday: 'Ngày lễ', locked: 'Đã khoá',
    };
    return [...new Set(this.days().map((d) => d.kind))].map((kind) => ({ kind, label: label[kind] }));
  });

  protected readonly hasConflict = computed(() => this.days().some((d) => !!d.conflict));

  /** Nhãn đọc được cho MỘT ô ngày — gộp mọi thông tin đang chỉ truyền bằng màu/hình.
   *  Trước đây nút chỉ chứa con số nên trình đọc màn hình đọc "18", không biết lễ/khoá/xung đột. */
  protected dayLabel(d: VnrCalendarDay): string {
    const kind: Record<VnrDayKind, string> = {
      workday: 'ngày làm việc', weekend: 'ngày nghỉ tuần', holiday: 'ngày lễ', locked: 'đã khoá',
    };
    const parts = [`Ngày ${d.day}`, kind[d.kind]];
    if (d.portion === 0.5) parts.push('nửa ngày');
    if (d.shift) parts.push(`ca ${d.shift}`);
    if (d.conflict) parts.push(`xung đột: ${d.conflict}`);
    if (this.isSel(d.date)) parts.push('đã chọn');
    else if (this.inRange(d.date)) parts.push('trong khoảng đã chọn');
    return parts.join(', ');
  }

  protected isSel(iso: string): boolean {
    const s = this.selected();
    return s.length > 0 && (iso === s[0] || iso === s[s.length - 1]);
  }

  protected inRange(iso: string): boolean {
    const s = this.selected();
    return s.length >= 2 && iso > s[0] && iso < s[s.length - 1];
  }

  protected pick(d: VnrCalendarDay): void {
    if (d.kind === 'locked') return;
    const cur = [...this.selected()];
    // click 1 → mốc đầu · click 2 → chốt khoảng · click 3 → bắt đầu lại
    const next = cur.length === 1 ? [cur[0], d.date].sort() : [d.date];
    this.selected.set(next);
    this.selectionChange.emit(next);
  }

  protected clear(): void {
    this.selected.set([]);
    this.selectionChange.emit([]);
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// TRAIT · money-policy
// ══════════════════════════════════════════════════════════════════════════════

export interface VnrExpenseRow {
  readonly id: string;
  readonly category: string;
  readonly quantity: number | null;
  readonly unitPrice: number | null;
  /** ĐÃ TÍNH bởi tầng nghiệp vụ — UI không nhân. */
  readonly amount: number | null;
  readonly policyState?: 'ok' | 'warn' | 'over';
  readonly policyMessage?: string | null;
}

export interface VnrExpenseTotal { readonly currency: string; readonly amount: number; readonly label?: string; }

export type VnrExpenseCellKey = 'category' | 'quantity' | 'unitPrice';
export interface VnrExpenseCellChange { readonly rowId: string; readonly key: VnrExpenseCellKey; readonly value: string | number | null; }

/**
 * Bảng chi phí có CHÍNH SÁCH.
 * RÀNG BUỘC KIẾN TRÚC (thực thi bằng THIẾT KẾ, không bằng lời nhắc): component này
 * KHÔNG tính `thành tiền = SL × đơn giá`, KHÔNG quy đổi tỷ giá, KHÔNG tự quyết "vượt hạn mức".
 * Nó nhận giá trị ĐÃ TÍNH và bắn `cellChange` để tầng business-rule tính lại rồi đẩy xuống.
 * ⇒ Dùng lại được cho dự toán / quyết toán / tạm ứng / bồi hoàn / phụ cấp.
 * Container hẹp ⇒ tự đổ về dạng thẻ (không cuộn ngang).
 */
@Component({
  selector: 'vnr-expense-table',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  template: `
    <div class="vnr-xt">
      <table class="vnr-xt__tb">
        <thead><tr>
          <th>Khoản mục</th><th class="n">SL</th><th class="n">Đơn giá</th><th class="n">Thành tiền</th>
          <!-- Cột thao tác không có tiêu đề nhìn thấy ⇒ đặt aria-label, tránh bị đọc là "cột trống" -->
          @if (!readonly()) { <th class="a" aria-label="Thao tác trên dòng"></th> }
        </tr></thead>
        <tbody>
          @for (r of rows(); track r.id; let i = $index) {
            <tr [attr.data-policy]="r.policyState || 'ok'">
              <td>
                @if (readonly()) { <span>{{ r.category }}</span> }
                <!-- Mọi ô nhập đều phải có nhãn KÈM SỐ DÒNG: bảng này không có <label> nào,
                     thiếu aria-label thì trình đọc màn hình chỉ đọc "ô nhập văn bản", không rõ cột nào dòng nào. -->
                @else { <input class="vnr-xt__in" [value]="r.category"
                  [attr.aria-label]="'Khoản mục, dòng ' + (i + 1)" (change)="cell(r.id, 'category', str($event))" /> }
                @if (r.policyMessage) { <span class="vnr-xt__pol" [attr.data-s]="r.policyState">{{ r.policyMessage }}</span> }
              </td>
              <td class="n">
                @if (readonly()) { <span>{{ r.quantity }}</span> }
                @else { <input class="vnr-xt__in n" type="number" min="0" [value]="r.quantity"
                  [attr.aria-label]="'Số lượng, dòng ' + (i + 1)" (change)="cell(r.id, 'quantity', num($event))" /> }
              </td>
              <td class="n">
                @if (readonly()) { <span>{{ fmt(r.unitPrice) }}</span> }
                @else { <input class="vnr-xt__in n" type="number" min="0" [value]="r.unitPrice"
                  [attr.aria-label]="'Đơn giá, dòng ' + (i + 1)" (change)="cell(r.id, 'unitPrice', num($event))" /> }
              </td>
              <!-- Thành tiền LUÔN read-only: công thức thuộc business-rule layer -->
              <td class="n amt">{{ fmt(r.amount) }}</td>
              @if (!readonly()) { <td class="a"><button type="button" class="vnr-xt__x"
                (click)="removeRow.emit(r.id)" [attr.aria-label]="'Xoá dòng ' + (i + 1)">✕</button></td> }
            </tr>
          } @empty {
            <tr><td class="vnr-xt__empty" [attr.colspan]="readonly() ? 4 : 5">Chưa có khoản chi phí nào.</td></tr>
          }
        </tbody>
        <tfoot>
          @for (t of totals(); track t.currency) {
            <tr><td [attr.colspan]="3">{{ t.label || 'Tổng cộng' }} ({{ t.currency }})</td>
              <td class="n amt">{{ fmt(t.amount) }}</td>@if (!readonly()) { <td></td> }</tr>
          }
        </tfoot>
      </table>

      <!-- Card fallback (container hẹp) — cùng dữ liệu, không cuộn ngang -->
      <div class="vnr-xt__cards">
        @for (r of rows(); track r.id) {
          <div class="vnr-xt__card" [attr.data-policy]="r.policyState || 'ok'">
            <div class="hd"><span class="nm">{{ r.category }}</span><span class="am">{{ fmt(r.amount) }}</span></div>
            <div class="bd"><span>SL: <b>{{ r.quantity }}</b></span><span>Đơn giá: <b>{{ fmt(r.unitPrice) }}</b></span></div>
            @if (r.policyMessage) { <div class="vnr-xt__pol" [attr.data-s]="r.policyState">{{ r.policyMessage }}</div> }
          </div>
        } @empty { <div class="vnr-xt__empty">Chưa có khoản chi phí nào.</div> }
        @for (t of totals(); track t.currency) {
          <div class="vnr-xt__ct"><span>{{ t.label || 'Tổng cộng' }} ({{ t.currency }})</span><b>{{ fmt(t.amount) }}</b></div>
        }
      </div>

      @if (!readonly()) {
        <div class="vnr-xt__ft"><button type="button" class="vnr-xt__add" (click)="addRow.emit()">+ Thêm khoản chi phí</button></div>
      }
    </div>
  `,
  styles: [`
    .vnr-xt__tb { inline-size: 100%; border-collapse: collapse; border: 1px solid var(--border-sub); border-radius: var(--radius-sm, 6px); overflow: hidden; }
    .vnr-xt__tb th { background: var(--bg-surface-subtle); font-size: var(--fs-11, 11px); text-transform: uppercase; letter-spacing: .3px;
      color: var(--text-soft); font-weight: var(--font-semibold, 600); text-align: start; padding: 8px 10px; border-block-end: 1px solid var(--border-soft); }
    .vnr-xt__tb td { padding: 6px 10px; border-block-end: 1px solid var(--border-soft); font-size: var(--fs-12, 12px); }
    .vnr-xt__tb tbody tr:last-child td { border-block-end: none; }
    .vnr-xt__tb .n { text-align: end; inline-size: 108px; }
    .vnr-xt__tb .a { inline-size: 38px; text-align: center; }
    /* Số/tiền: tabular-nums để so sánh được bằng mắt */
    .vnr-xt__tb .amt, .vnr-xt__in.n { font-variant-numeric: tabular-nums; }
    .vnr-xt__tb .amt { font-weight: var(--font-semibold, 600); }
    .vnr-xt__tb tr[data-policy='warn'] { background: var(--warning-bg); }
    .vnr-xt__tb tr[data-policy='over'] { background: var(--error-bg); }
    /* Vượt chính sách: tô nền KÈM CHỮ — không chỉ dựa vào màu */
    .vnr-xt__pol { display: block; margin-block-start: 3px; font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); }
    .vnr-xt__pol[data-s='warn'] { color: var(--warning-base); }
    .vnr-xt__pol[data-s='over'] { color: var(--error-base); }
    .vnr-xt__in { inline-size: 100%; block-size: 28px; border: 1px solid transparent; border-radius: var(--radius-xs, 4px); background: transparent;
      padding: 0 6px; font: inherit; font-size: var(--fs-12, 12px); color: var(--text-strong); }
    .vnr-xt__in.n { text-align: end; }
    .vnr-xt__in:hover { border-color: var(--border-sub); background: var(--bg-surface); }
    .vnr-xt__in:focus-visible { outline: 2px solid var(--primary-base); outline-offset: 1px; }
    .vnr-xt__in:focus { outline: none; border-color: var(--primary-base); background: var(--bg-surface); }
    .vnr-xt__tb tfoot td { background: var(--bg-surface-subtle); font-weight: var(--font-bold, 700); border-block-start: 1px solid var(--border-sub); }
    .vnr-xt__empty { text-align: center; color: var(--text-soft); padding: 16px; font-size: var(--fs-12, 12px); }
    .vnr-xt__x { border: none; background: none; color: var(--text-soft); cursor: pointer; border-radius: var(--radius-xs, 4px); inline-size: 24px; block-size: 24px; }
    .vnr-xt__x:hover { background: var(--error-bg); color: var(--error-base); }
    .vnr-xt__ft { padding-block-start: 8px; }
    .vnr-xt__add { border: 1px dashed var(--border-strong); background: none; color: var(--text-body);
      border-radius: var(--radius-sm, 6px); padding: 6px 12px; font: inherit; font-size: var(--fs-12, 12px); cursor: pointer; }
    .vnr-xt__add:hover { border-color: var(--primary-base); color: var(--primary-base); }
    .vnr-xt__cards { display: none; flex-direction: column; gap: 8px; }
    .vnr-xt__card { border: 1px solid var(--border-sub); border-radius: var(--radius-sm, 6px); padding: 10px 12px; background: var(--bg-surface); }
    .vnr-xt__card[data-policy='warn'] { background: var(--warning-bg); }
    .vnr-xt__card[data-policy='over'] { background: var(--error-bg); border-color: var(--error-base); }
    .vnr-xt__card .hd { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; }
    .vnr-xt__card .nm { font-weight: var(--font-semibold, 600); font-size: var(--fs-13, 13px); }
    .vnr-xt__card .am { font-weight: var(--font-bold, 700); font-variant-numeric: tabular-nums; }
    .vnr-xt__card .bd { display: flex; flex-wrap: wrap; gap: 12px; margin-block-start: 4px; font-size: var(--fs-12, 12px); color: var(--text-sub); }
    .vnr-xt__card .bd b { color: var(--text-strong); font-variant-numeric: tabular-nums; }
    .vnr-xt__ct { display: flex; justify-content: space-between; padding: 10px 12px; background: var(--bg-surface-subtle);
      border: 1px solid var(--border-sub); border-radius: var(--radius-sm, 6px); font-weight: var(--font-bold, 700); }
    .vnr-xt__ct b { font-variant-numeric: tabular-nums; }
    /* Đổi vai theo BỀ RỘNG CONTAINER (không phải viewport) */
    @container vnrform (max-width: 559px) { .vnr-xt__tb { display: none; } .vnr-xt__cards { display: flex; } }
  `],
})
export class VnrExpenseTable {
  readonly rows = input.required<readonly VnrExpenseRow[]>();
  readonly totals = input<readonly VnrExpenseTotal[]>([]);
  readonly readonly = input(false);
  readonly cellChange = output<VnrExpenseCellChange>();
  readonly addRow = output<void>();
  readonly removeRow = output<string>();

  protected cell(rowId: string, key: VnrExpenseCellKey, value: string | number | null): void {
    this.cellChange.emit({ rowId, key, value });
  }
  protected str(e: Event): string { return (e.target as HTMLInputElement).value; }
  protected num(e: Event): number | null {
    const v = (e.target as HTMLInputElement).value;
    return v === '' ? null : Number(v);
  }
  /** Chỉ ĐỊNH DẠNG hiển thị — không phải tính toán nghiệp vụ. */
  protected fmt(v: number | null | undefined): string {
    return v == null ? '—' : new Intl.NumberFormat('vi-VN').format(v);
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// TRAIT · comparison + effective-dated
// ══════════════════════════════════════════════════════════════════════════════

export interface VnrComparisonRow {
  readonly label: string;
  readonly current: string | null;
  readonly proposed: string | null;
  /** Chênh lệch ĐÃ TÍNH bởi caller, vd "+16,7%". */
  readonly delta?: string | null;
  /** Ý nghĩa theo NGHIỆP VỤ — không suy từ dấu +/−. */
  readonly tone?: 'neutral' | 'up' | 'down' | 'warn';
  /** false = không đổi ⇒ làm mờ để mắt bỏ qua. */
  readonly changed?: boolean;
}

export interface VnrScheduledChange { readonly effectiveDate: string; readonly summary: string; readonly conflict?: boolean; }

/**
 * So sánh "hiện tại → đề xuất". Một component phủ CẢ trait `comparison` lẫn `effective-dated`
 * vì bản chất giống nhau, chỉ khác ở ngày hiệu lực + danh sách thay đổi đã lên lịch.
 * RANH GIỚI: không tự tính delta nghiệp vụ (chênh giờ công, % tăng lương) — caller truyền vào.
 * Lý do: cùng một cặp số nhưng "tăng" là tốt hay xấu tuỳ nghiệp vụ, UI không được đoán.
 */
@Component({
  selector: 'vnr-change-comparison',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  template: `
    <div class="vnr-cc">
      @if (effectiveDate()) {
        <div class="vnr-cc__eff">
          <span class="k">Hiệu lực từ</span><span class="v">{{ effectiveDate() }}</span>
          @if (isFuture()) { <span class="vnr-cc__bg">Lên lịch trước</span> }
        </div>
      }
      <div class="vnr-cc__hd"><span>{{ currentLabel() }}</span><span></span><span>{{ proposedLabel() }}</span></div>
      @for (r of rows(); track r.label) {
        <div class="vnr-cc__row" [class.is-same]="r.changed === false" [attr.data-tone]="r.tone || 'neutral'">
          <div class="c"><span class="lb">{{ r.label }}</span><span class="val">{{ r.current || '—' }}</span></div>
          <div class="ar">→</div>
          <div class="c"><span class="lb lbm">{{ r.label }}</span><span class="val new">{{ r.proposed || '—' }}</span>
            @if (r.delta) { <span class="dl">{{ r.delta }}</span> }</div>
        </div>
      }
      @if (impacted().length) {
        <div class="vnr-cc__im"><span class="t">Ảnh hưởng tới</span>
          @for (m of impacted(); track m) { <span class="chip">{{ m }}</span> }</div>
      }
      @if (scheduled().length) {
        <div class="vnr-cc__sc"><span class="t">Thay đổi đã lên lịch</span>
          @for (s of scheduled(); track s.effectiveDate) {
            <div class="r" [class.cf]="s.conflict"><span class="d">{{ s.effectiveDate }}</span><span class="s">{{ s.summary }}</span>
              @if (s.conflict) { <span class="w">Trùng ngày hiệu lực</span> }</div>
          }</div>
      }
    </div>
  `,
  styles: [`
    .vnr-cc { border: 1px solid var(--border-sub); border-radius: var(--radius-sm, 6px); background: var(--bg-surface); overflow: hidden; }
    .vnr-cc__eff { display: flex; align-items: center; gap: 8px; padding: 10px 12px; background: var(--primary-bg-subtle);
      border-block-end: 1px solid var(--border-soft); font-size: var(--fs-12, 12px); }
    .vnr-cc__eff .k { color: var(--text-sub); }
    .vnr-cc__eff .v { font-weight: var(--font-semibold, 600); color: var(--primary-base); font-variant-numeric: tabular-nums; }
    .vnr-cc__bg { margin-inline-start: auto; font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); color: var(--info-base);
      background: var(--info-bg); border-radius: var(--radius-full); padding: 2px 9px; }
    .vnr-cc__hd { display: grid; grid-template-columns: 1fr 26px 1fr; gap: 8px; padding: 6px 12px; background: var(--bg-surface-subtle);
      font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); text-transform: uppercase; letter-spacing: .3px; color: var(--text-soft); }
    .vnr-cc__row { display: grid; grid-template-columns: 1fr 26px 1fr; gap: 8px; align-items: center; padding: 9px 12px;
      border-block-start: 1px solid var(--border-soft); }
    /* Không đổi ⇒ mờ để mắt tập trung vào phần THỰC SỰ thay đổi */
    .vnr-cc__row.is-same { opacity: .55; }
    .vnr-cc__row .c { display: flex; flex-direction: column; gap: 2px; min-inline-size: 0; }
    .vnr-cc__row .lb { font-size: var(--fs-11, 11px); color: var(--text-soft); }
    .vnr-cc__row .lbm { display: none; }
    .vnr-cc__row .val { font-size: var(--fs-13, 13px); color: var(--text-body); word-break: break-word; }
    .vnr-cc__row .val.new { font-weight: var(--font-semibold, 600); color: var(--text-strong); }
    .vnr-cc__row .ar { text-align: center; color: var(--text-soft); }
    .vnr-cc__row .dl { font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); font-variant-numeric: tabular-nums; }
    /* Hướng thay đổi do NGHIỆP VỤ quyết (tone), không suy từ dấu số */
    .vnr-cc__row[data-tone='up'] .val.new, .vnr-cc__row[data-tone='up'] .dl { color: var(--success-base); }
    .vnr-cc__row[data-tone='down'] .val.new, .vnr-cc__row[data-tone='down'] .dl { color: var(--error-base); }
    .vnr-cc__row[data-tone='warn'] .val.new, .vnr-cc__row[data-tone='warn'] .dl { color: var(--warning-base); }
    .vnr-cc__im { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; padding: 10px 12px; border-block-start: 1px solid var(--border-soft); }
    .vnr-cc__im .t, .vnr-cc__sc .t { font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); text-transform: uppercase; letter-spacing: .3px; color: var(--text-soft); }
    .vnr-cc__im .chip { font-size: var(--fs-11, 11px); font-weight: var(--font-medium, 500); color: var(--info-base);
      background: var(--info-bg); border-radius: var(--radius-full); padding: 3px 10px; }
    .vnr-cc__sc { padding: 10px 12px; border-block-start: 1px solid var(--border-soft); background: var(--bg-surface-subtle); }
    .vnr-cc__sc .r { display: flex; align-items: baseline; gap: 8px; font-size: var(--fs-12, 12px); margin-block-start: 5px; }
    .vnr-cc__sc .d { font-variant-numeric: tabular-nums; color: var(--text-sub); flex: none; }
    .vnr-cc__sc .r.cf .s { color: var(--warning-base); font-weight: var(--font-medium, 500); }
    .vnr-cc__sc .w { font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); color: var(--warning-base); background: var(--warning-bg); border-radius: var(--radius-full); padding: 2px 8px; }
    /* Container hẹp ⇒ xếp dọc; nhãn chuyển sang vế "đề xuất" để vẫn đọc được cặp */
    @container vnrform (max-width: 559px) {
      .vnr-cc__hd { display: none; }
      .vnr-cc__row { grid-template-columns: 1fr; gap: 2px; }
      .vnr-cc__row .ar { text-align: start; transform: rotate(90deg); inline-size: 16px; }
      .vnr-cc__row .lbm { display: block; }
    }
  `],
})
export class VnrChangeComparison {
  readonly rows = input.required<readonly VnrComparisonRow[]>();
  readonly currentLabel = input('Hiện tại');
  readonly proposedLabel = input('Đề xuất');
  readonly effectiveDate = input<string | null>(null);
  readonly isFuture = input(false);
  readonly impacted = input<readonly string[]>([]);
  readonly scheduled = input<readonly VnrScheduledChange[]>([]);
}

// ══════════════════════════════════════════════════════════════════════════════
// LAYOUT · repeatable — danh sách item cùng cấu trúc
// ══════════════════════════════════════════════════════════════════════════════

/**
 * Nhóm item lặp lại: thêm / xoá / nhân bản / chọn item chính.
 * Nội dung MỖI item do caller cấp qua `itemTemplate` (nhận $implicit = item, index = i)
 * ⇒ dùng lại được cho: bằng cấp · chứng chỉ · người phụ thuộc · liên hệ khẩn cấp ·
 * tài khoản ngân hàng · lịch trình công tác · người tham gia · mục tiêu OKR.
 * RANH GIỚI: không tự validate item (caller truyền `itemError`), không giới hạn logic nghiệp vụ.
 */
@Component({
  selector: 'vnr-repeatable-group',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [NgTemplateOutlet, HrmEmpty],
  template: `
    <div class="vnr-rp">
      @for (it of items(); track it.id; let i = $index) {
        <div class="vnr-rp__it" [class.is-primary]="it.id === primaryId()" [class.has-err]="!!it.error">
          <div class="vnr-rp__hd">
            <span class="ix">{{ i + 1 }}</span>
            <span class="ti">{{ it.title || (itemLabel() + ' ' + (i + 1)) }}</span>
            @if (it.id === primaryId()) { <span class="pm">Chính</span> }
            <span class="sp"></span>
            @if (allowPrimary() && it.id !== primaryId()) {
              <button type="button" class="vnr-rp__b" (click)="setPrimary.emit(it.id)">Đặt làm chính</button>
            }
            @if (allowDuplicate()) {
              <button type="button" class="vnr-rp__b" (click)="duplicate.emit(it.id)">Nhân bản</button>
            }
            @if (canRemove()) {
              <button type="button" class="vnr-rp__b is-danger" (click)="remove.emit(it.id)" aria-label="Xoá">✕</button>
            }
          </div>
          <div class="vnr-rp__bd">
            <ng-container *ngTemplateOutlet="itemTemplate(); context: { $implicit: it.data, index: i, id: it.id }" />
          </div>
          @if (it.error) { <div class="vnr-rp__err">{{ it.error }}</div> }
        </div>
      } @empty {
        <hrm-empty preset="no-data" [description]="emptyText()" />
      }

      @if (canAdd()) {
        <button type="button" class="vnr-rp__add" (click)="add.emit()">+ {{ addLabel() }}</button>
      } @else {
        <div class="vnr-rp__limit">Đã đạt tối đa {{ max() }} {{ itemLabel().toLowerCase() }}.</div>
      }
    </div>
  `,
  styles: [`
    .vnr-rp { display: flex; flex-direction: column; gap: var(--space-2-5, 10px); }
    .vnr-rp__it { border: 1px solid var(--border-sub); border-radius: var(--radius-sm, 6px); background: var(--bg-surface); overflow: hidden; }
    .vnr-rp__it.is-primary { border-color: var(--primary-base); }
    .vnr-rp__it.has-err { border-color: var(--error-base); }
    .vnr-rp__hd { display: flex; align-items: center; gap: var(--space-2, 8px); padding: 7px 10px;
      background: var(--bg-surface-subtle); border-block-end: 1px solid var(--border-soft); }
    .vnr-rp__hd .ix { inline-size: 20px; block-size: 20px; border-radius: var(--radius-full); background: var(--bg-surface);
      border: 1px solid var(--border-sub); display: inline-flex; align-items: center; justify-content: center;
      font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); color: var(--text-sub); flex: none; }
    .vnr-rp__hd .ti { font-size: var(--fs-12, 12px); font-weight: var(--font-semibold, 600); color: var(--text-strong); }
    .vnr-rp__hd .pm { font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); color: var(--primary-base);
      background: var(--primary-bg-subtle); border-radius: var(--radius-full); padding: 1px 8px; }
    .vnr-rp__hd .sp { margin-inline-start: auto; }
    .vnr-rp__b { border: none; background: none; color: var(--text-sub); font: inherit; font-size: var(--fs-11, 11px);
      cursor: pointer; border-radius: var(--radius-xs, 4px); padding: 3px 7px; }
    .vnr-rp__b:hover { background: var(--bg-surface); color: var(--primary-base); }
    .vnr-rp__b.is-danger:hover { background: var(--error-bg); color: var(--error-base); }
    .vnr-rp__bd { padding: 10px; }
    .vnr-rp__err { padding: 6px 10px; background: var(--error-bg); color: var(--error-base);
      font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); }
    .vnr-rp__add { border: 1px dashed var(--border-strong); background: none; color: var(--text-body);
      border-radius: var(--radius-sm, 6px); padding: 7px 12px; font: inherit; font-size: var(--fs-12, 12px); cursor: pointer; }
    .vnr-rp__add:hover { border-color: var(--primary-base); color: var(--primary-base); }
    .vnr-rp__limit { font-size: var(--fs-11, 11px); color: var(--text-soft); }
  `],
})
export class VnrRepeatableGroup {
  readonly items = input.required<readonly VnrRepeatableItem[]>();
  readonly itemTemplate = input.required<TemplateRef<unknown>>();
  readonly itemLabel = input('Mục');
  readonly addLabel = input('Thêm mục');
  readonly emptyText = input('Chưa có mục nào.');
  readonly primaryId = input<string | null>(null);
  readonly allowPrimary = input(false);
  readonly allowDuplicate = input(false);
  /** Giới hạn số item (null = không giới hạn). */
  readonly max = input<number | null>(null);
  readonly minItems = input(0);

  readonly add = output<void>();
  readonly remove = output<string>();
  readonly duplicate = output<string>();
  readonly setPrimary = output<string>();

  protected canAdd(): boolean {
    const m = this.max();
    return m == null || this.items().length < m;
  }
  protected canRemove(): boolean { return this.items().length > this.minItems(); }
}

export interface VnrRepeatableItem {
  readonly id: string;
  readonly title?: string | null;
  readonly error?: string | null;
  /** Dữ liệu truyền vào template của caller. */
  readonly data: unknown;
}

// ══════════════════════════════════════════════════════════════════════════════
// TRAIT · attachment — tài liệu & chứng từ
// ══════════════════════════════════════════════════════════════════════════════

export interface VnrDocumentItem {
  readonly id: string;
  readonly type: string;
  readonly number?: string | null;
  readonly issueDate?: string | null;
  readonly expiryDate?: string | null;
  readonly authority?: string | null;
  readonly fileName?: string | null;
  /** Do domain service tính (còn hạn / sắp hết / hết hạn) — UI không tự so ngày. */
  readonly expiryState?: 'valid' | 'soon' | 'expired' | null;
  readonly expiryNote?: string | null;
  readonly verification?: 'pending' | 'verified' | 'rejected' | null;
  /** Dữ liệu nhạy cảm: che số + chặn tải nếu không đủ quyền. */
  readonly sensitive?: boolean;
  readonly canDownload?: boolean;
}

/**
 * Nhóm tài liệu: loại · số · ngày cấp · ngày hết hạn · nơi cấp · file · xác minh.
 * RANH GIỚI: KHÔNG tự tính "sắp hết hạn" (khác nhau theo loại giấy tờ và chính sách) —
 * domain service tính rồi truyền `expiryState`. KHÔNG tự quyết quyền tải: caller cấp `canDownload`.
 * Dùng cho: CCCD · hộ chiếu · visa · hợp đồng · bằng cấp · giấy nghỉ ốm · quyết định · hoá đơn.
 */
@Component({
  selector: 'vnr-document-group',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [HrmEmpty],
  template: `
    <div class="vnr-dg">
      @for (d of documents(); track d.id) {
        <div class="vnr-dg__it" [attr.data-exp]="d.expiryState || 'valid'">
          <div class="vnr-dg__hd">
            <span class="ty">{{ d.type }}</span>
            @if (d.number) {
              <span class="no">{{ d.sensitive ? mask(d.number) : d.number }}</span>
            }
            @if (d.verification) {
              <span class="vf" [attr.data-v]="d.verification">{{ verifLabel(d.verification) }}</span>
            }
            <span class="sp"></span>
            @if (!readonly()) {
              <button type="button" class="vnr-dg__b is-danger" (click)="remove.emit(d.id)" aria-label="Xoá tài liệu">✕</button>
            }
          </div>
          <div class="vnr-dg__meta">
            @if (d.issueDate)  { <span>Ngày cấp: <b>{{ d.issueDate }}</b></span> }
            @if (d.expiryDate) { <span>Hết hạn: <b>{{ d.expiryDate }}</b></span> }
            @if (d.authority)  { <span>Nơi cấp: <b>{{ d.authority }}</b></span> }
          </div>
          @if (d.expiryNote) {
            <div class="vnr-dg__warn" [attr.data-exp]="d.expiryState">{{ d.expiryNote }}</div>
          }
          <div class="vnr-dg__file">
            @if (d.fileName) {
              <span class="fn">{{ d.fileName }}</span>
              @if (d.sensitive && d.canDownload === false) {
                <span class="lk">Không đủ quyền tải xuống</span>
              } @else {
                <button type="button" class="vnr-dg__b" (click)="download.emit(d.id)">Tải xuống</button>
              }
            } @else {
              <span class="fn is-none">Chưa đính kèm tệp</span>
            }
          </div>
        </div>
      } @empty {
        <hrm-empty preset="no-data" [description]="emptyText()" />
      }
      @if (!readonly()) {
        <button type="button" class="vnr-dg__add" (click)="add.emit()">+ {{ addLabel() }}</button>
      }
    </div>
  `,
  styles: [`
    .vnr-dg { display: flex; flex-direction: column; gap: var(--space-2, 8px); }
    .vnr-dg__it { border: 1px solid var(--border-sub); border-radius: var(--radius-sm, 6px);
      background: var(--bg-surface); padding: 9px 11px; }
    .vnr-dg__it[data-exp='soon']    { border-color: var(--warning-border); background: var(--warning-bg); }
    .vnr-dg__it[data-exp='expired'] { border-color: var(--error-base); background: var(--error-bg); }
    .vnr-dg__hd { display: flex; align-items: center; gap: var(--space-2, 8px); flex-wrap: wrap; }
    .vnr-dg__hd .ty { font-size: var(--fs-13, 13px); font-weight: var(--font-semibold, 600); color: var(--text-strong); }
    .vnr-dg__hd .no { font-size: var(--fs-12, 12px); color: var(--text-body); font-variant-numeric: tabular-nums; }
    .vnr-dg__hd .sp { margin-inline-start: auto; }
    .vnr-dg__hd .vf { font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); border-radius: var(--radius-full); padding: 1px 8px; }
    .vnr-dg__hd .vf[data-v='verified'] { color: var(--success-base); background: var(--success-bg); }
    .vnr-dg__hd .vf[data-v='pending']  { color: var(--text-sub); background: var(--bg-surface-subtle); }
    .vnr-dg__hd .vf[data-v='rejected'] { color: var(--error-base); background: var(--error-bg); }
    .vnr-dg__meta { display: flex; flex-wrap: wrap; gap: 12px; margin-block-start: 4px;
      font-size: var(--fs-12, 12px); color: var(--text-sub); }
    .vnr-dg__meta b { color: var(--text-body); font-variant-numeric: tabular-nums; }
    .vnr-dg__warn { margin-block-start: 5px; font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); }
    .vnr-dg__warn[data-exp='soon']    { color: var(--warning-base); }
    .vnr-dg__warn[data-exp='expired'] { color: var(--error-base); }
    .vnr-dg__file { display: flex; align-items: center; gap: var(--space-2, 8px); margin-block-start: 6px;
      padding-block-start: 6px; border-block-start: 1px dashed var(--border-sub); }
    .vnr-dg__file .fn { font-size: var(--fs-12, 12px); color: var(--text-body); }
    .vnr-dg__file .fn.is-none { color: var(--text-soft); font-style: italic; }
    .vnr-dg__file .lk { font-size: var(--fs-11, 11px); color: var(--text-soft); }
    .vnr-dg__b { border: none; background: none; color: var(--primary-base); font: inherit;
      font-size: var(--fs-11, 11px); font-weight: var(--font-medium, 500); cursor: pointer; border-radius: var(--radius-xs, 4px); padding: 3px 7px; }
    .vnr-dg__b:hover { background: var(--primary-bg-subtle); }
    .vnr-dg__b.is-danger { color: var(--text-soft); }
    .vnr-dg__b.is-danger:hover { background: var(--error-bg); color: var(--error-base); }
    .vnr-dg__add { border: 1px dashed var(--border-strong); background: none; color: var(--text-body);
      border-radius: var(--radius-sm, 6px); padding: 7px 12px; font: inherit; font-size: var(--fs-12, 12px); cursor: pointer; }
    .vnr-dg__add:hover { border-color: var(--primary-base); color: var(--primary-base); }
  `],
})
export class VnrDocumentGroup {
  readonly documents = input.required<readonly VnrDocumentItem[]>();
  readonly readonly = input(false);
  readonly addLabel = input('Thêm tài liệu');
  readonly emptyText = input('Chưa có tài liệu nào.');
  readonly add = output<void>();
  readonly remove = output<string>();
  readonly download = output<string>();

  /** Che bớt số giấy tờ nhạy cảm — chỉ hiển thị, dữ liệu gốc không đổi. */
  protected mask(v: string): string {
    return v.length <= 4 ? '••••' : '•'.repeat(Math.max(0, v.length - 4)) + v.slice(-4);
  }
  protected verifLabel(v: NonNullable<VnrDocumentItem['verification']>): string {
    return v === 'verified' ? 'Đã xác minh' : v === 'rejected' ? 'Bị từ chối' : 'Chờ xác minh';
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// TRAIT · approval — bọc HrmApprovalFlow đã có, KHÔNG dựng lại stepper
// ══════════════════════════════════════════════════════════════════════════════

/** Cảnh báo chính sách / xung đột kèm theo yêu cầu — do domain service sinh. */
export interface VnrPolicyWarning {
  readonly level: 'info' | 'warn' | 'error';
  readonly message: string;
}

/**
 * Khối phê duyệt của một yêu cầu: luồng duyệt + cảnh báo chính sách + tóm tắt tác động.
 *
 * TÁI DÙNG: stepper dùng thẳng `hrm-approval-flow` (đã có trong hrm-ui, nhận `HrmApprovalStep[]`).
 * Shell này KHÔNG vẽ lại stepper — chỉ bổ sung phần mà archetype "Approval Decision" cần:
 * cảnh báo chính sách, tác động, và slot cho thanh quyết định (hrm-action-bar do caller cắm vào).
 *
 * RANH GIỚI: không tự quyết ai được duyệt, không tự sinh cảnh báo — caller truyền vào.
 */
@Component({
  selector: 'vnr-approval-panel',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [HrmApprovalFlow, HrmAlert],
  template: `
    <div class="vnr-ap">
      @if (warnings().length) {
        <div class="vnr-ap__warns">
          @for (w of warnings(); track w.message) {
            <hrm-alert [type]="alertType(w.level)" [message]="w.message" />
          }
        </div>
      }

      <hrm-approval-flow [steps]="steps()" [collapsedCount]="collapsedCount()" />

      @if (impacted().length) {
        <div class="vnr-ap__im">
          <span class="t">Tác động khi duyệt</span>
          @for (m of impacted(); track m) { <span class="chip">{{ m }}</span> }
        </div>
      }

      <!-- Slot cho thanh quyết định (Duyệt / Từ chối / Yêu cầu chỉnh sửa / Uỷ quyền) -->
      <ng-content />
    </div>
  `,
  styles: [`
    .vnr-ap { display: flex; flex-direction: column; gap: var(--space-2-5, 10px); }
    .vnr-ap__warns { display: flex; flex-direction: column; gap: var(--space-1-5, 6px); }
    .vnr-ap__im { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-2, 8px); }
    .vnr-ap__im .t { font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); text-transform: uppercase;
      letter-spacing: .3px; color: var(--text-soft); }
    .vnr-ap__im .chip { font-size: var(--fs-11, 11px); font-weight: var(--font-medium, 500); color: var(--info-base);
      background: var(--info-bg); border-radius: var(--radius-full); padding: 3px 10px; }
  `],
})
export class VnrApprovalPanel {
  readonly steps = input.required<HrmApprovalStep[]>();
  readonly warnings = input<readonly VnrPolicyWarning[]>([]);
  readonly impacted = input<readonly string[]>([]);
  readonly collapsedCount = input(0);

  /** Quy đổi mức cảnh báo NGHIỆP VỤ sang kiểu của hrm-alert — chỉ khác tên ('warn' ↔ 'warning'),
   *  giữ nguyên 3 mức đang dùng thay vì ép tất cả về một màu. */
  protected alertType(level: VnrPolicyWarning['level']): HrmAlertType {
    return level === 'warn' ? 'warning' : level;
  }
}
